function engCurrentScreen(){
  if(document.querySelector('.lcOverlay')) return 'Live';

  const rh=document.querySelector('.rhOverlay');
  if(rh){
    const t=(rh.querySelector('.rhTab.active')?.textContent||'Results').trim().toLowerCase();
    return t.includes('my') ? 'My Results' : 'Results';
  }

  if(document.querySelector('#plp-match-centre')) return 'Match Centre';

  const active=document.querySelector('#nav button.active');
  const key=active?.dataset?.v||'';
  const names={home:'Home',predict:'Predict',table:'Table',stats:'Stats',ai:'AI',chat:'Chat',more:'More'};
  if(names[key]) return names[key];

  const txt=(active?.textContent||'').replace(/[^\p{L}\p{N} ]/gu,'').trim();
  return txt||'Home';
}

async function engResolve(){
  try{
    const {data:{session}}=await sbTabs.auth.getSession();
    if(!session) return false;

    const {data,error}=await sbTabs.from('league_members')
      .select('league_id,role,status')
      .eq('user_id',session.user.id)
      .eq('status','active');

    if(error) throw error;
    const m=(data||[])[0];
    if(!m) return false;

    engLeagueId=m.league_id;
    engRole=m.role||'player';

    const {data:leagueRows,error:leagueErr}=await sbTabs.from('leagues')
      .select('created_by')
      .eq('id',engLeagueId)
      .limit(1);
    if(leagueErr) throw leagueErr;
    engOwner=String((leagueRows||[])[0]?.created_by||'')===String(session.user.id);

    return true;
  }catch(e){
    console.warn('Engagement resolve:',e);
    return false;
  }
}

async function engSend(eventType='heartbeat',screen=null){
  if(!engLeagueId) return;
  try{
    const {error}=await sbTabs.rpc('track_app_activity',{
      p_league_id:engLeagueId,
      p_screen:screen||engCurrentScreen(),
      p_event_type:eventType
    });
    if(error) throw error;
  }catch(e){
    if(eventType!=='heartbeat') console.warn('Engagement event:',e);
  }
}

function engScheduleScreenCheck(force=false){
  clearTimeout(engScheduleScreenCheck.t);
  engScheduleScreenCheck.t=setTimeout(async()=>{
    const screen=engCurrentScreen();
    if(force || screen!==engLastScreen){
      engLastScreen=screen;
      await engSend('screen_view',screen);
    }
    engMaybeInjectCard();
  },180);
}

function engAgo(iso){
  if(!iso) return 'Not seen yet';
  const sec=Math.max(0,Math.floor((Date.now()-new Date(iso).getTime())/1000));
  if(sec<60) return 'now';
  if(sec<3600) return `${Math.floor(sec/60)}m ago`;
  if(sec<86400) return `${Math.floor(sec/3600)}h ago`;
  return `${Math.floor(sec/86400)}d ago`;
}

function engTime(iso){
  if(!iso) return '—';
  return new Intl.DateTimeFormat('en-GB',{
    timeZone:'Europe/London',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'
  }).format(new Date(iso));
}

function engEventLabel(e){
  if(e==='app_open') return 'Opened app';
  if(e==='screen_view') return 'Viewed';
  if(e==='prediction_saved') return 'Saved prediction';
  if(e==='chat_message') return 'Sent chat message';
  return e||'Activity';
}

async function engGetDashboard(){
  if(!engOwner||!engLeagueId) return null;
  const {data,error}=await sbTabs.rpc('get_admin_engagement',{
    p_league_id:engLeagueId,
    p_days:7
  });
  if(error) throw error;
  return data||{};
}

