function engDashboardMarkup(d){
  const online=d.online_now||[];
  const screens=d.screen_views_today||[];
  const members=d.members||[];
  const recent=d.recent_activity||[];

  const onlineHtml=online.length ? online.map(x=>`
    <div class="engPerson">
      <div class="engPersonName">${engEsc(x.badge||'⚽')} ${engEsc(x.team_name||x.display_name||'Player')}
        <small>${engEsc(x.display_name||'')} · ${engEsc(x.screen||'App')}</small>
      </div>
      <div class="engPersonRight"><span class="engOnline">Online</span><br>${engEsc(engAgo(x.last_seen))}</div>
    </div>
  `).join('') : `<div class="engEmpty" style="padding:14px">Nobody else is showing as active right now.</div>`;

  const screenHtml=screens.length
    ? `<div class="engScreenRows">${screens.map(x=>`<span class="engScreenChip">${engEsc(x.screen)} · ${Number(x.views||0)}</span>`).join('')}</div>`
    : `<div class="notice">Screen-view tracking starts from this version of the app.</div>`;

  const memberHtml=members.length ? members.map(x=>`
    <div class="engPerson">
      <div class="engPersonName">${engEsc(x.badge||'⚽')} ${engEsc(x.team_name||x.display_name||'Player')}
        <small>${engEsc(x.display_name||'')} · ${x.screen?engEsc(x.screen):'No tracked screen yet'}</small>
      </div>
      <div class="engPersonRight">
        ${x.online?'<span class="engOnline">Online</span>':engEsc(engAgo(x.last_seen))}
        <br>${Number(x.opens_window||0)} opens / 7d
        ${x.last_prediction?`<br>Pick: ${engEsc(engAgo(x.last_prediction))}`:''}
      </div>
    </div>
  `).join('') : `<div class="notice">No active members found.</div>`;

  const recentHtml=recent.length ? recent.slice(0,20).map(x=>`
    <div class="engEvent">
      <div><b>${engEsc(x.badge||'⚽')} ${engEsc(x.team_name||x.display_name||'Player')}</b>
        <small>${engEsc(engEventLabel(x.event_type))}${x.screen?` · ${engEsc(x.screen)}`:''}</small>
      </div>
      <div style="text-align:right;color:#716f82;white-space:nowrap">${engEsc(engAgo(x.created_at))}</div>
    </div>
  `).join('') : `<div class="notice">Activity history will build from now onward.</div>`;

  return `
    <div class="engStats">
      <div class="engStat"><b>${online.length}</b><span>Online now</span></div>
      <div class="engStat"><b>${Number(d.active_today||0)}</b><span>Active today</span></div>
      <div class="engStat"><b>${Number(d.opens_today||0)}</b><span>App opens today</span></div>
      <div class="engStat"><b>${Number(d.peak_active_today||0)}</b><span>Peak active</span></div>
    </div>

    <div class="engPanel">
      <div class="engPanelHead"><h2>🟢 Live now</h2><span>Last ~100 seconds</span></div>
      ${onlineHtml}
    </div>

    <div class="engPanel">
      <div class="engPanelHead"><h2>Today’s screens</h2><span>Views</span></div>
      ${screenHtml}
      <div class="notice" style="margin-top:9px">
        Active users: <b>${Number(d.active_today||0)}</b> today ·
        <b>${Number(d.active_7d||0)}</b> in 7 days ·
        <b>${Number(d.active_30d||0)}</b> in 30 days
      </div>
    </div>

    <div class="engPanel">
      <details class="engDetails">
        <summary><span>All league members</span><span>${members.length}</span></summary>
        <div style="padding:0 10px">${memberHtml}</div>
      </details>
    </div>

    <div class="engPanel">
      <div class="engPanelHead"><h2>Recent activity</h2><span>Latest non-heartbeat events</span></div>
      ${recentHtml}
    </div>

    <div class="engFoot">
      Private league-owner analytics. “Online” means the signed-in app was visible and checked in within about 100 seconds.
      No GPS, message contents, prediction values or keystrokes are collected by this tracker.
    </div>
  `;
}

async function engRenderDashboard(){
  const overlay=document.querySelector('.engOverlay');
  if(!overlay) return;
  const body=overlay.querySelector('.engBody');
  if(!body) return;

  try{
    const d=await engGetDashboard();
    body.innerHTML=engDashboardMarkup(d||{});
  }catch(e){
    console.warn('Engagement dashboard:',e);
    body.innerHTML=`<div class="engEmpty"><b>Couldn’t load engagement.</b><br>${engEsc(e.message||String(e))}</div>`;
  }
}

async function engOpenDashboard(){
  if(!engOwner) return;
  document.querySelector('.engOverlay')?.remove();

  const overlay=document.createElement('div');
  overlay.className='engOverlay';
  overlay.innerHTML=`
    <div class="engShell">
      <div class="engHead">
        <div class="engHeadTop">
          <div>
            <div class="engEyebrow">Private admin</div>
            <div class="engTitle">App Engagement</div>
            <div class="engSub">Who’s on now · visits · screen interest · last seen</div>
          </div>
          <div class="engHeadBtns">
            <button type="button" class="engHeadBtn" data-eng-refresh>↻</button>
            <button type="button" class="engHeadBtn" data-eng-close>✕</button>
          </div>
        </div>
      </div>
      <div class="engBody"><div class="engLoading">Loading engagement…</div></div>
    </div>
  `;
  document.body.appendChild(overlay);
  document.body.style.overflow='hidden';

  overlay.querySelector('[data-eng-close]').addEventListener('click',engCloseDashboard);
  overlay.querySelector('[data-eng-refresh]').addEventListener('click',engRenderDashboard);

  await engRenderDashboard();
  clearInterval(engDashboardTimer);
  engDashboardTimer=setInterval(()=>{
    if(document.querySelector('.engOverlay')) engRenderDashboard();
  },30000);
}

function engCloseDashboard(){
  document.querySelector('.engOverlay')?.remove();
  document.body.style.overflow='';
  clearInterval(engDashboardTimer);
  engDashboardTimer=null;
  engRefreshQuick();
}

async function engStart(){
  if(engStarted) return;
  const ok=await engResolve();
  if(!ok){
    setTimeout(engStart,2500);
    return;
  }

  engStarted=true;
  engAddStyles();
  engLastScreen=engCurrentScreen();

  await engSend('app_open',engLastScreen);
  await engSend('screen_view',engLastScreen);

  engMaybeInjectCard();

  engHeartbeatTimer=setInterval(()=>{
    if(document.visibilityState==='visible'){
      engSend('heartbeat',engCurrentScreen());
    }
  },45000);

  document.addEventListener('visibilitychange',()=>{
    if(document.visibilityState==='visible'){
      engSend('heartbeat',engCurrentScreen());
      engScheduleScreenCheck(true);
    }
  });

  document.addEventListener('click',()=>{
    setTimeout(()=>engScheduleScreenCheck(false),100);
  },true);

  new MutationObserver(()=>{
    clearTimeout(engInjectTimer);
    engInjectTimer=setTimeout(()=>engScheduleScreenCheck(false),120);
  }).observe(document.body,{childList:true,subtree:true});

  sbTabs.auth.onAuthStateChange((_event,sess)=>{
    if(!sess){
      engLeagueId=null;
      engRole=null;
      engOwner=false;
      engStarted=false;
      clearInterval(engHeartbeatTimer);
      engHeartbeatTimer=null;
    }
  });
}

engAddStyles();
setTimeout(engStart,600);

